Problem:
A landscaping company provides services from an expert or an apprentice. An expert costs the company 500 dollars for each shift and can care for 100 square meters of land whereas an apprentice costs the company 300 dollars for each shift and can care for 80 square meters of land. Because of the price to the customer, the company expects the demand of the public to want at least twice as many apprentices than experts. However, there are loyal customers that prefer the experts. Therefore, at least 10% of shifts must be expert shifts. The company must care for 5000 square meters of land. How many of each type of service should be used to minimize the total cost to the company?

Model and facts:
{
 "model": {
  "variables": [
   {
    "name": "expert shifts",
    "lower": 0.0,
    "upper": null,
    "integer": true
   },
   {
    "name": "apprentice shifts",
    "lower": 0.0,
    "upper": null,
    "integer": true
   }
  ],
  "objective": {
   "sense": "min",
   "terms": [
    {
     "var": "expert shifts",
     "coef": 500.0
    },
    {
     "var": "apprentice shifts",
     "coef": 300.0
    }
   ]
  },
  "constraints": [
   {
    "name": "land care",
    "terms": [
     {
      "var": "expert shifts",
      "coef": 100.0
     },
     {
      "var": "apprentice shifts",
      "coef": 80.0
     }
    ],
    "sense": ">=",
    "rhs": 5000.0
   },
   {
    "name": "apprentice demand",
    "terms": [
     {
      "var": "apprentice shifts",
      "coef": 1.0
     },
     {
      "var": "expert shifts",
      "coef": -2.0
     }
    ],
    "sense": ">=",
    "rhs": 0.0
   },
   {
    "name": "expert share",
    "terms": [
     {
      "var": "expert shifts",
      "coef": 0.9
     },
     {
      "var": "apprentice shifts",
      "coef": -0.1
     }
    ],
    "sense": ">=",
    "rhs": 0.0
   }
  ]
 },
 "facts": {
  "objective": 19700.0,
  "values": {
   "expert shifts": 7.0,
   "apprentice shifts": 54.0
  },
  "binding": [],
  "slack": {
   "land care": 20.0,
   "apprentice demand": 40.0,
   "expert share": 0.9
  },
  "shadow_prices": null,
  "limits": {
   "land care": {
    "dropped_improves": true,
    "loosened_improves": false
   },
   "apprentice demand": {
    "dropped_improves": false,
    "loosened_improves": false
   },
   "expert share": {
    "dropped_improves": true,
    "loosened_improves": true
   }
  }
 }
}
